import pysam
ref_fa = pysam.FastaFile('/task/work/ref.fa')

def get_indel_af(bam_path, chrom, pos, op, seq):
    # pos is 0-based coordinate of the event
    bam = pysam.AlignmentFile(bam_path)
    alt_frags = set()
    total_frags = set()
    for read in bam.fetch(chrom, max(0, pos - 20), pos + 20):
        if read.is_secondary or read.is_supplementary or read.mapping_quality < 20:
            continue
        # Check if read spans the position pos
        if read.reference_start <= pos and read.reference_end > pos:
            total_frags.add(read.query_name)
        curr_pos = read.reference_start
        read_pos = 0
        for cop, clen in read.cigartuples:
            if cop == 0:
                curr_pos += clen
                read_pos += clen
            elif cop == 1:
                if op == 'INS' and curr_pos == pos and read.query_sequence[read_pos:read_pos+clen] == seq:
                    alt_frags.add(read.query_name)
                read_pos += clen
